    27  #ifndef HB_VECTOR_HH
    28  #define HB_VECTOR_HH
    29
    30  #include "hb.hh"
    31  #include "hb-array.hh"
    32  #include "hb-null.hh"
    33
    34
    35  template <typename Type>
    36  struct hb_vector_t
    37  {
    38    typedef Type item_t;
    39    static constexpr unsigned item_size = hb_static_size (Type);
    40
    41    hb_vector_t ()  { init (); }
    42    hb_vector_t (const hb_vector_t &o)
    43    {
    44      init ();
    45      alloc (o.length);
    46      hb_copy (o, *this);
    47    }
    48    hb_vector_t (hb_vector_t &&o)
    49    {
    50      allocated = o.allocated;
    51      length = o.length;
    52      arrayZ_ = o.arrayZ_;
    53      o.init ();
    54    }
    55    ~hb_vector_t () { fini (); }
    56
    57    unsigned int length;
    58    private:
    59    int allocated; /* == -1 means allocation failed. */
    60    Type *arrayZ_;
    61    public:
    62
    63    void init ()
    64    {
    65      allocated = length = 0;
    66      arrayZ_ = nullptr;
    67    }
    68
    69    void fini ()
    70    {
    71      if (arrayZ_)
    72        free (arrayZ_);
    73      init ();
    74    }
    75    void fini_deep ()
    76    {
    77      Type *array = arrayZ();
    78      unsigned int count = length;
    79      for (unsigned int i = 0; i < count; i++)
    80        array[i].fini ();
    81      fini ();
    82    }
    83
    84    void reset () { resize (0); }
    85
    86    hb_vector_t& operator = (const hb_vector_t &o)
    87    {
    88      reset ();
    89      alloc (o.length);
    90      hb_copy (o, *this);
    91      return *this;
    92    }
    93    hb_vector_t& operator = (hb_vector_t &&o)
    94    {
    95      fini ();
    96      allocated = o.allocated;
    97      length = o.length;
    98      arrayZ_ = o.arrayZ_;
    99      o.init ();
   100      return *this;
   101    }
   102
   103    hb_bytes_t as_bytes () const
   104    { return hb_bytes_t ((const char *) arrayZ(), length * item_size); }
   105
   106    bool operator == (const hb_vector_t &o) const { return as_array () == o.as_array (); }
   107    uint32_t hash () const { return as_array ().hash (); }
   108
   109    const Type * arrayZ () const { return arrayZ_; }
   110          Type * arrayZ ()       { return arrayZ_; }
   111
   112    Type& operator [] (int i_)
   113    {
   114      unsigned int i = (unsigned int) i_;
   115      if (unlikely (i >= length))
   116        return Crap (Type);
   117      return arrayZ()[i];
   118    }
   119    const Type& operator [] (int i_) const
   120    {
   121      unsigned int i = (unsigned int) i_;
   122      if (unlikely (i >= length))
   123        return Null(Type);
   124      return arrayZ()[i];
   125    }
   126
   127    Type& tail () { return (*this)[length - 1]; }
   128    const Type& tail () const { return (*this)[length - 1]; }
   129
   130    explicit operator bool () const { return length; }
   131    unsigned get_size () const { return length * item_size; }
   132
   133    /* Sink interface. */
   134    template <typename T>
   135    hb_vector_t& operator << (T&& v) { push (hb_forward<T> (v)); return *this; }
   136
   137    hb_array_t<      Type> as_array ()       { return hb_array (arrayZ(), length); }
   138    hb_array_t<const Type> as_array () const { return hb_array (arrayZ(), length); }
   139
   140    /* Iterator. */
   141    typedef hb_array_t<const Type>   iter_t;
   142    typedef hb_array_t<      Type> writer_t;
   143      iter_t   iter () const { return as_array (); }
   144    writer_t writer ()       { return as_array (); }
   145    operator   iter_t () const { return   iter (); }
   146    operator writer_t ()       { return writer (); }
   147
   148    hb_array_t<const Type> sub_array (unsigned int start_offset, unsigned int count) const
   149    { return as_array ().sub_array (start_offset, count);}
   150    hb_array_t<const Type> sub_array (unsigned int start_offset, unsigned int *count = nullptr /* IN/OUT */) const
   151    { return as_array ().sub_array (start_offset, count);}
   152    hb_array_t<Type> sub_array (unsigned int start_offset, unsigned int count)
   153    { return as_array ().sub_array (start_offset, count);}
   154    hb_array_t<Type> sub_array (unsigned int start_offset, unsigned int *count = nullptr /* IN/OUT */)
   155    { return as_array ().sub_array (start_offset, count);}
   156
   157    hb_sorted_array_t<Type> as_sorted_array ()
   158    { return hb_sorted_array (arrayZ(), length); }
   159    hb_sorted_array_t<const Type> as_sorted_array () const
   160    { return hb_sorted_array (arrayZ(), length); }
   161
   162    template <typename T> explicit operator T * () { return arrayZ(); }
   163    template <typename T> explicit operator const T * () const { return arrayZ(); }
   164
   165    Type * operator  + (unsigned int i) { return arrayZ() + i; }
   166    const Type * operator  + (unsigned int i) const { return arrayZ() + i; }
   167
   168    Type *push ()
   169    {
   170      if (unlikely (!resize (length + 1)))
   171        return &Crap(Type);
   172      return &arrayZ()[length - 1];
   173    }
   174    template <typename T>
   175    Type *push (T&& v)
   176    {
   177      Type *p = push ();
   178      *p = hb_forward<T> (v);
   179      return p;
   180    }
